# On-budget receipts (column 2) and Off-budget receipts (column 3)\n\ndata = {\n    1991: (760375, 293885),   # 1996 bulletin\n    1992: (789266, 302426),   # 1996 bulletin\n    1993: (841241, 311934),   # 1996 bulletin\n    1994: (922161, 335026),   # 1996 bulletin\n    1995: (999496, 351080),   # 1996 bulletin\n    1996: (1085271, 367492),  # 2001 bulletin (actual)\n    1997: (1186987, 391989),  # 2001 bulletin\n    1998: (1305621, 415800),  # 2001 bulletin\n    1999: (1382834, 444468),  # 2001 bulletin\n    2000: (1544455, 480583),  # 2001 bulletin\n    2001: (1483525, 507519),  # 2006 bulletin (actual)\n    2002: (1337730, 515321),  # 2006 bulletin\n    2003: (1258265, 523842),  # 2006 bulletin\n    2004: (1345040, 534744),  # 2006 bulletin\n    2005: (1575874, 577475),  # 2006 bulletin\n    2006: (1797946, 608382),  # 2011 bulletin (actual)\n    2007: (1932359, 635088),  # 2011 bulletin\n    2008: (1865279, 658045),  # 2011 bulletin\n    2009: (1450355, 654010),  # 2011 bulletin\n    2010: (1530058, 631688),  # 2011 bulletin\n}\n\non_budget = np.array([data[y][0] for y in range(1991, 2011)])\noff_budget = np.array([data[y][1] for y in range(1991, 2011)])\n\nprint(\"On-budget receipts:\", on_budget)\nprint(\"Off-budget receipts:\", off_budget)\n\n# Calculate R-squared using numpy\n# Linear regression: off_budget = a + b * on_budget\n# Or we can calculate correlation coefficient and square it\n\n# Calculate correlation coefficient\ncorrelation = np.corrcoef(on_budget, off_budget)[0, 1]\nr_squared = correlation ** 2\n\nprint(f\"\\nCorrelation coefficient: {correlation}\")\nprint(f\"R-squared: {r_squared}\")\nprint(f\"R-squared (rounded to 4 decimal places): {round(r_squared, 4)}\")\n\n# Let's also verify with sklearn\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.metrics import r2_score\n\nX = on_budget.reshape(-1, 1)\ny = off_budget\n\nmodel = LinearRegression()\nmodel.fit(X, y)\ny_pred = model.predict(X)\nr2 = r2_score(y, y_pred)\n\nprint(f\"\\nSklearn R-squared: {r2}\")\nprint(f\"Sklearn R-squared (rounded): {round(r2, 4)}\")\n\n# Print the regression line\nprint(f\"\\nRegression line: off_budget = {model.intercept_} + {model.coef_[0]} * on_budget\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
